// Build-info constants (card 4.E4 About panel). Injected by vite.config.ts
// `define` from ui/package.json at config load — the only path by which the
// package manifest's name/version reach UI code without escaping ui/src
// (doc 08 §8 boundary) and without a hardcoded literal that can drift.

declare const __UI_PACKAGE_NAME__: string;
declare const __UI_PACKAGE_VERSION__: string;
